const runs = $input.first().json.workflow_runs || [];
const d = runs[0];

if (!d || d.conclusion !== 'failure') {
  return [];
}

return [{ json: {
  run_id: d.id,
  sha: d.head_sha,
  url: d.html_url,
  run_name: d.name,
  message_commit: (d.head_commit && d.head_commit.message) || '',
  auteur: (d.head_commit && d.head_commit.author && d.head_commit.author.name) || ''
} }];

const jobs = ($input.first().json.jobs || []).filter(j => j.conclusion === 'failure');
const ctx = $('3. Échec ? sinon on s\'arrête').first().json;

if (!jobs.length) {
  return [];
}

const lignes = [];
for (const j of jobs) {
  const etapes = (j.steps || []).filter(s => s.conclusion === 'failure').map(s => s.name);
  lignes.push(`- ${j.name}${etapes.length ? ' — étape en échec : ' + etapes.join(', ') : ''}`);
}

const sujet = `Une exécution CI a échoué sur la branche main.\n\n` +
  `Run : ${ctx.run_name}\n` +
  `Jobs en échec :\n${lignes.join('\n')}\n` +
  `Dernier commit : ${ctx.message_commit}\n` +
  `Lien : ${ctx.url}\n`;

const systeme = [
  'Tu es un analyste CI. Tu reçois le nom des jobs et des étapes en échec, rien de plus.',
  'Tu réponds en français, en 5 lignes maximum, dans ce format exact :',
  '',
  'Cause probable : une phrase.',
  'Étape à corriger : le chemin de fichier ou le nom du test le plus vraisemblable.',
  'Vérification : la commande exacte à lancer en local pour reproduire.',
  'Correctif : une phrase, pas de code.',
].join('\n');

return [{ json: { ...ctx, corps_analyse: JSON.stringify({
  model: 'deepseek-flash',
  stream: false,
  max_tokens: 700,
  extra_body: { thinking: { type: 'disabled' } },
  messages: [
    { role: 'system', content: systeme },
    { role: 'user', content: sujet },
  ],
}) } }];
